function prose(markup){
 // tag attributes, embedded pixels, CSS and JS are not editorial copy.
 return markup.split(/(<script\b[^>]*>[\s\S]*?<\/script>|<style\b[^>]*>[\s\S]*?<\/style>|<[^>]+>)/gi)
  .map(part=>part.startsWith('<')?part:wording.reduce((s,[from,to])=>s.replaceAll(from,to),part)).join('');
}

